mapper.select:
SELECT 
FROM ultary_report
WHERE reporter_user_no = #{reporterUserNo}
  AND target_type = #{targetType}
  AND status IN ('REQUESTED', 'CONFIRMED', 'ON_HOLD')

  AND target_user_no = #{targetUserNo}


  AND target_feed_id = #{targetFeedId}


  AND target_comment_id = #{targetCommentId}


  AND target_reply_id = #{targetReplyId}

LIMIT 1

SELECT




		r.status = #{status}


		AND (
			r.created_at < (
				SELECT c2.created_at FROM ultary_report c2 WHERE c2.report_id = #{cursorReportId}
			)
			OR (
				r.created_at = (
					SELECT c2.created_at FROM ultary_report c2 WHERE c2.report_id = #{cursorReportId}
				)
				AND r.report_id < #{cursorReportId}
			)
		)


ORDER BY r.created_at DESC, r.report_id DESC
LIMIT #{limit}

